"""
Claude가 세션 종료 시 자동 호출하는 토큰 추가 스크립트
사용: python .status/add_tokens.py <토큰수> "<작업명>"
"""
import json, os, sys
from datetime import datetime

STATUS_DIR = os.path.dirname(os.path.abspath(__file__))
TOKEN_FILE = os.path.join(STATUS_DIR, 'token_usage.json')


def main():
    if len(sys.argv) < 3:
        print('사용: python add_tokens.py <토큰수> "<작업명>"')
        sys.exit(1)

    try:
        tokens = int(sys.argv[1])
    except ValueError:
        print('토큰 수는 정수여야 합니다.')
        sys.exit(1)

    task = sys.argv[2]
    today = datetime.now().strftime('%Y-%m-%d')

    # 기존 데이터 로드
    if os.path.exists(TOKEN_FILE):
        with open(TOKEN_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if data.get('date') != today:
            data = {'date': today, 'used': 0, 'daily_limit': data.get('daily_limit', 5000000),
                    'plan': data.get('plan', 'Max'), 'sessions': []}
    else:
        data = {'date': today, 'used': 0, 'daily_limit': 5000000, 'plan': 'Max', 'sessions': []}

    data['used'] = data.get('used', 0) + tokens
    data.setdefault('sessions', []).append({
        'task': task,
        'tokens': tokens,
        'time': datetime.now().strftime('%H:%M:%S'),
    })

    with open(TOKEN_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


if __name__ == '__main__':
    main()

