"""
Claude Code Stop 훅 — transcript 기반 토큰 자동 추정 및 기록
Stop 훅이 실행될 때 stdin으로 JSON 페이로드를 받아 transcript를 분석한다.
"""
import io, json, os, sys
from datetime import datetime

STATUS_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, STATUS_DIR)
import show_tokens

# UTF-8 출력 설정
if hasattr(sys.stdout, 'buffer'):
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')

MIN_NEW_TOKENS = 300  # 이 미만이면 노이즈로 간주하여 기록 생략


def estimate_tokens(transcript_path):
    """JSONL transcript를 읽어 전체 텍스트 기반 토큰 수 추정 (chars / 4)."""
    if not os.path.exists(transcript_path):
        return 0
    total_chars = 0
    try:
        with open(transcript_path, 'r', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.strip()
                if not line:
